#!/usr/bin/env python3
import os,pathlib,tempfile,subprocess
src=pathlib.Path(__file__).resolve().parents[2]/'tools/elytrix-airdrop/src/ru/rooyzee/elytrixairdrop/patch'
f={
'org/bukkit/GameMode.java':'package org.bukkit;public enum GameMode {SURVIVAL,CREATIVE,SPECTATOR}',
'org/bukkit/util/Vector.java':'package org.bukkit.util;public class Vector {public double y;public Vector setY(double y){this.y=y;return this;}}',
'org/bukkit/World.java':'package org.bukkit;import java.util.*;import org.bukkit.entity.Player;public class World {public List<Player> players=new ArrayList<>();public List<Player> getPlayers(){return players;}}',
'org/bukkit/Location.java':'package org.bukkit;public class Location {World w;double x,y,z;public Location(World w,double x,double y,double z){this.w=w;this.x=x;this.y=y;this.z=z;}public World getWorld(){return w;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}}',
'org/bukkit/entity/Player.java':'package org.bukkit.entity;import java.util.*;import org.bukkit.*;import org.bukkit.util.Vector;public class Player {public boolean ground=true,online=true,dead=false,flying=false,vehicle=false;public GameMode mode=GameMode.SURVIVAL;public Location loc;public Vector v=new Vector();public int changes;public UUID id=UUID.randomUUID();public boolean isOnline(){return online;}public boolean isDead(){return dead;}public GameMode getGameMode(){return mode;}public boolean isFlying(){return flying;}public boolean isInsideVehicle(){return vehicle;}public Location getLocation(){return loc;}public UUID getUniqueId(){return id;}public boolean isOnGround(){return ground;}public Vector getVelocity(){return v;}public void setVelocity(Vector v){this.v=v;changes++;}}',
'org/bukkit/Bukkit.java':'package org.bukkit;public class Bukkit {public static Scheduler getScheduler(){return new Scheduler();}public static class Scheduler {public void runTaskTimer(Object p,Runnable r,long a,long b){}}}',
'ru/rooyzee/elytrixairdrop/airdrops/Airdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops;public enum Airdrop {PEACEFUL,SKY}',
'ru/rooyzee/elytrixairdrop/airdrops/ActiveAirdrop.java':'package ru.rooyzee.elytrixairdrop.airdrops;public class ActiveAirdrop {public Airdrop type=Airdrop.PEACEFUL;public Airdrop getType(){return type;}public long getEndTime(){return 12345;}}',
'ru/rooyzee/elytrixairdrop/airdrops/types/Peace.java':'package ru.rooyzee.elytrixairdrop.airdrops.types;import org.bukkit.Location;import ru.rooyzee.elytrixairdrop.airdrops.*;public class Peace extends ActiveAirdrop {private boolean activated,unlocked,looted;private long unlockTime;private Location chestLoc;public Peace(Location l){chestLoc=l;}public void activate(long t){activated=true;unlockTime=t;}public void looted(){looted=true;}}',
'ru/rooyzee/elytrixairdrop/Main.java':'package ru.rooyzee.elytrixairdrop;import ru.rooyzee.elytrixairdrop.airdrops.*;public class Main {public Manager m=new Manager();public Manager getAirdropManager(){return m;}public static class Manager {public ActiveAirdrop a;public ActiveAirdrop getActive(){return a;}}}',
'Test.java':'''import java.lang.reflect.*;import java.util.*;import org.bukkit.*;import org.bukkit.entity.*;import ru.rooyzee.elytrixairdrop.*;import ru.rooyzee.elytrixairdrop.airdrops.types.*;import ru.rooyzee.elytrixairdrop.patch.*;public class Test {static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static void tick(Object obj)throws Exception{Method m=obj.getClass().getDeclaredMethod("tick");m.setAccessible(true);m.invoke(obj);}static Map<UUID,Long> map(Object obj,String n)throws Exception{Field f=obj.getClass().getDeclaredField(n);f.setAccessible(true);return (Map<UUID,Long>)f.get(obj);}public static void main(String[] args)throws Exception{World w=new World();Player p=new Player();p.loc=new Location(w,0,64,0);w.players.add(p);Main plugin=new Main();Peace event=new Peace(new Location(w,0,64,0));plugin.m.a=event;Constructor<PeacefulMechanics> c=PeacefulMechanics.class.getDeclaredConstructor(Main.class);c.setAccessible(true);Object m=c.newInstance(plugin);long before=System.currentTimeMillis();tick(m);long d=map(m,"next").get(p.id)-before;ok(d>=5000&&d<=10010,"delay range");map(m,"next").put(p.id,0L);tick(m);ok(p.changes==1&&p.v.y>=1.05&&p.v.y<=1.15,"launch");p.ground=false;map(m,"slam").put(p.id,0L);tick(m);ok(p.changes==2&&p.v.y==-1.5,"downward slam");p.ground=true;event.activate(System.currentTimeMillis()+15000L);map(m,"next").put(p.id,0L);map(m,"slam").put(p.id,0L);tick(m);ok(p.changes==2&&map(m,"next").isEmpty()&&map(m,"slam").isEmpty(),"15 second cutoff");event.activate(System.currentTimeMillis()+60000L);tick(m);p.mode=GameMode.CREATIVE;map(m,"next").put(p.id,0L);tick(m);ok(p.changes==2&&map(m,"next").isEmpty(),"creative excluded");ok(PeacefulMechanics.endTime(event)==12345&&PeacefulMechanics.lifetime(event)==900000,"normal timeout");event.looted();ok(PeacefulMechanics.endTime(event)>System.currentTimeMillis()+299000&&PeacefulMechanics.lifetime(event)==Long.MAX_VALUE,"loot grace timeout");System.out.println("Peaceful launch intervals, cutoff, slam, exclusions and grace OK");}}'''
}
with tempfile.TemporaryDirectory() as tmp:
 p=pathlib.Path(tmp)
 for n,c in f.items():
  q=p/n;q.parent.mkdir(parents=True,exist_ok=True);q.write_text(c)
 subprocess.run([os.environ['JAVA'],'-jar',os.environ['ECJ'],'-21','-proc:none','-nowarn','-d',tmp,*[str(p/n) for n in f],str(src/'PeacefulMechanics.java'),str(src/'LaunchMath.java')],check=True)
 subprocess.run([os.environ['JAVA'],'-Xverify:all','-cp',tmp,'Test'],check=True)
